// Generated by build-guided-source.mjs; shared website artwork.
window.buildSocialScene=function(){
  var actionIcons = {
    /* Chrome config */
    newTab:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round">' +
        '<path d="M12 5.6v12.8M5.6 12h12.8"/></svg>',
    bookmark:
      '<svg viewBox="0 0 24 24" fill="currentColor">' +
        '<path d="M12 3.6l2.5 5.1 5.6.8-4.1 4 1 5.6-5-2.7-5 2.7 1-5.6-4.1-4 5.6-.8z"/></svg>',
    download:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">' +
        '<path d="M12 3.8v10.4M7.4 9.9l4.6 4.3 4.6-4.3M4.6 19.4h14.8"/></svg>',
    password:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
        '<circle cx="8.4" cy="8.6" r="4.6"/>' +
        '<path d="M11.7 11.9L20 20.2M17.2 17.4l2.1-2.1M14.6 14.8l2.1-2.1"/></svg>',
    atSign:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">' +
        '<circle cx="12" cy="12" r="3.9"/>' +
        '<path d="M15.9 8.1v5.2a2.9 2.9 0 0 0 5.1 1.9A9.4 9.4 0 1 0 17.4 19"/></svg>',
    reload:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">' +
        '<path d="M19.2 12a7.2 7.2 0 1 1-2.2-5.2"/><path d="M19.6 4.2v4.6H15"/></svg>',

    /* Photoshop config */
    brush:
      '<svg viewBox="0 0 24 24" fill="currentColor">' +
        '<path d="M18.6 3.6a2 2 0 0 1 2.8 2.8l-7.7 7.7-2.8-2.8z"/>' +
        '<path d="M9.4 13.2l2.4 2.4c-.6 2.5-2.3 4-4.7 4-1 0-2-.3-2.7-.7 1.1-.5 1.4-1.5 1.6-2.5.2-1.4 1-3.2 3.4-3.2z"/></svg>',
    layers:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round">' +
        '<path d="M12 3.4l8.6 4.5-8.6 4.5-8.6-4.5z"/><path d="M4.2 12.4L12 16.5l7.8-4.1"/>' +
        '<path d="M4.2 16.4L12 20.5l7.8-4.1"/></svg>',
    textTool:
      '<svg viewBox="0 0 24 24" fill="currentColor">' +
        '<path d="M4.6 4.2h14.8v3.2h-5.8v12.4h-3.2V7.4H4.6z"/></svg>',
    crop:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">' +
        '<path d="M6.4 2.6v15H21.4"/><path d="M2.6 6.4h15v15"/></svg>',
    undo:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">' +
        '<path d="M4.8 12a7.2 7.2 0 1 0 2.2-5.2"/><path d="M4.4 4.2v4.6H9"/></svg>',
    exportFile:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">' +
        '<path d="M12 15.6V4.4M7.4 9l4.6-4.6L16.6 9M4.6 19.4h14.8"/></svg>'
  };
  var icons = Object.assign({}, QpIcons, QpBrandIcons, actionIcons);

  /* ── The grid every configuration is drawn on: center, ring 1 (6), then
     ring 2 (12). No config fills all of it — each one lights up its own
     slots and the rest aren't rendered, so the two menus differ in size
     and silhouette as well as in content. ── */
  var cells = QuickPickHex.CELLS_R2;

  /* ── The two configurations, as slot index → icon. Index 0 is the center
     hex, which carries the focused app's own icon — the clearest signal
     that the menu came up "inside" that app.

     Chrome is a tight 7: a browser needs a handful of things fast.
     Photoshop is 9 — the same core plus one slot out to each side, and
     those two carry the neighbouring apps in the creative suite. Same
     hotkey, visibly different menu. ── */
  var CONFIGS = {
    chrome: {
      app: "chrome",
      title: "QuickPick Docs — Google Chrome",
      label: "Google Chrome",
      slots: {
        0: "chrome",
        1: "newTab", 2: "bookmark", 3: "download",
        4: "password", 5: "atSign", 6: "reload"
      }
    },
    photoshop: {
      app: "photoshop",
      title: "hero-shot.psd — Adobe Photoshop",
      label: "Adobe Photoshop",
      slots: {
        0: "photoshop",
        1: "brush", 2: "layers", 3: "textTool", 4: "undo", 5: "crop", 6: "exportFile",
        // Ring 2 is axial, so a horizontal neighbour is r = -c/2, not r = 0:
        // {-2,1} is 9 o'clock and {2,-1} is 3 o'clock. ({-2,0} and {2,0}
        // sit at 10 and 4 o'clock.)
        18: "lightroom",  // 9 o'clock
        12: "illustrator" // 3 o'clock
      }
    }
  };

  var WORLD = { width: 760, height: 740 };
  /* The camera framing and the summon point are set independently here:
     the shot has to hold the whole app window, while the menu wants to sit
     lower, in the middle of the window's body rather than riding up over
     its title bar. Both configs summon at the same point — that's the
     claim the slide is making — so this moves them together. */
  var FOCUS = { x: 380, y: 370, zoom: 1 };
  var summonX = 380, summonY = 350;

  var qp = QuickPickHex.create(document.getElementById("qpDemo"), {
    cells: cells,
    bindings: [], // every slot is filled in by activate() below
    icons: icons,
    stageWidth: 380,
    stageHeight: 370,
    world: WORLD,
    camera: {x:380,y:395,zoom:.9},
    appBar: {apps:["chrome","photoshop"].map(name=>({run:true,icon:icons[name].replace("<svg ","<svg class=\"qp-app-icon\" ")}))}
  });

  QpDesktop.build(qp, {
    shortcuts: [
      { icon: "recycleBin", label: "Recycle Bin" },
      { icon: "abletonLive", label: "Ableton Live" }
    ],
    taskbar: [
      "fileExplorer",
      { icon: "chrome", run: true },
      { icon: "photoshop", run: true },
      "msTeams", "outlook", "spotify"
    ]
  });

  /* ── The two app windows, stacked in the same rect. Chrome and the body
     container come from qp-window.js/.css; `small: true` picks the preset
     sized for a floating window rather than a maximized one. ── */
  function makeWin(cfg, bodyHTML) {
    return QpWindow.build(qp, {
      className: "qp-app-win",
      small: true,
      icon: icons[cfg.app],
      title: cfg.title,
      bodyHTML: bodyHTML,
      before: qp.win // above the desktop, below QuickPick
    }).el;
  }

  var winChrome = makeWin(CONFIGS.chrome,
    '<div class="qp-fw-body fwb-browser">' +
      '<div class="fw-tabs"><div class="fw-tab on"></div><div class="fw-tab"></div><div class="fw-tab"></div></div>' +
      '<div class="fw-toolbar"><div class="fw-addr"></div></div>' +
      '<div class="fw-page">' +
        '<div class="fw-hero"></div>' +
        '<div class="fw-line" style="width:78%"></div>' +
        '<div class="fw-line" style="width:62%"></div>' +
        '<div class="fw-line" style="width:70%"></div>' +
        '<div class="fw-line" style="width:44%"></div>' +
      "</div>" +
    "</div>");

  var winPhotoshop = makeWin(CONFIGS.photoshop,
    '<div class="qp-fw-body fwb-editor">' +
      '<div class="fw-tools">' +
        '<div class="fw-tool on"></div><div class="fw-tool"></div><div class="fw-tool"></div>' +
        '<div class="fw-tool"></div><div class="fw-tool"></div><div class="fw-tool"></div>' +
      "</div>" +
      '<div class="fw-canvas"><div class="fw-art"></div></div>' +
      '<div class="fw-layers">' +
        '<div class="fw-layer on"></div><div class="fw-layer"></div>' +
        '<div class="fw-layer"></div><div class="fw-layer"></div>' +
      "</div>" +
    "</div>");


return {qp,icons,CONFIGS,winChrome,winPhotoshop};
};
